CREATE TABLE apps(id TEXT PRIMARY KEY, org_id TEXT NOT NULL REFERENCES organizations(id), name TEXT NOT NULL CHECK(length(name) BETWEEN 1 AND 128), slug TEXT NOT NULL, owner_kind TEXT NOT NULL DEFAULT 'independent' CHECK(owner_kind IN ('independent', 'solution')), managed_by TEXT, status TEXT NOT NULL DEFAULT 'created' CHECK(status IN ('created', 'ready', 'building', 'live', 'failed')), active_deployment_id TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(org_id, slug), CHECK((owner_kind = 'independent' AND managed_by IS NULL) OR (owner_kind = 'solution' AND managed_by IS NOT NULL)));
CREATE INDEX apps_org ON apps(org_id);
CREATE TABLE app_revisions(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, revision INTEGER NOT NULL, files_json TEXT NOT NULL CHECK(length(files_json) <= 16384), deps_json TEXT NOT NULL CHECK(length(deps_json) <= 4096), validation TEXT NOT NULL DEFAULT 'pending' CHECK(validation IN ('pending', 'valid', 'invalid')), failures_json TEXT, created_at TEXT NOT NULL, UNIQUE(app_id, revision));
CREATE TABLE app_deployments(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, revision INTEGER NOT NULL, bundle_json TEXT NOT NULL CHECK(length(bundle_json) <= 16384), content_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE app_jobs(id TEXT PRIMARY KEY, app_id TEXT NOT NULL REFERENCES apps(id) ON DELETE CASCADE, revision INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'queued' CHECK(status IN ('queued', 'running', 'succeeded', 'failed')), error_json TEXT, created_at TEXT NOT NULL, started_at TEXT, finished_at TEXT);
CREATE INDEX app_jobs_app ON app_jobs(app_id, created_at DESC, id DESC);
